// Reset per-run state and seed the revenue-band queue.
//
// CompanyWall caps anonymous search at ~60 results (3 pages x 20) PER QUERY,
// with no total count shown. A band that comes back at the cap is therefore
// truncated, not complete -- so we bisect it and try the halves. This is the
// only way to reach companies past the 60th without a logged-in session.
const s = $getWorkflowStaticData('global');
const cfg = $('Config').first().json;

s.written = 0;
s.skipped = 0;
s.failedPages = [];
s.failedProfiles = [];
s.loggedSample = 0;
s.bandsProcessed = 0;
s.bandCount = 0;
s.currentBand = null;
s.completedBands = [];
s.cappedBands = [];
// Seed bands come from the revenue_bands field, e.g.
//   "0-100000, 100000-400000, 400000-1000000, 1000000-2000000"
// Any seed band that comes back at the cap is bisected automatically, so these
// are starting points, not a promise that each one is small enough.
const parseBands = (spec) => {
  const out = [];
  for (const part of String(spec || '').split(',')) {
    const t = part.trim();
    if (!t) continue;
    const m = t.match(/^(\d+)\s*-\s*(\d+)$/);
    if (!m) { console.log(`!! Ignoring unparseable band "${t}" (expected "from-to", digits only)`); continue; }
    const from = Number(m[1]);
    const to = Number(m[2]);
    if (to < from) { console.log(`!! Ignoring reversed band "${t}"`); continue; }
    out.push({ from, to });
  }
  return out;
};

let bands = parseBands(cfg.revenue_bands);
if (!bands.length) {
  bands = [{ from: Number(cfg.revenue_from), to: Number(cfg.revenue_to) }];
  console.log('revenue_bands empty or unusable -> falling back to a single revenue_from..revenue_to band.');
}

// Gaps lose companies silently, so shout about them. Overlaps are fine (dedup).
const sorted = [...bands].sort((a, b) => a.from - b.from);
const lo = Number(cfg.revenue_from);
const hi = Number(cfg.revenue_to);
if (sorted[0].from > lo) {
  console.log(`!! GAP: nothing covers ${lo} - ${sorted[0].from} EUR. Companies in that range will NOT be found.`);
}
for (let i = 1; i < sorted.length; i++) {
  if (sorted[i].from > sorted[i - 1].to) {
    console.log(`!! GAP: nothing covers ${sorted[i - 1].to} - ${sorted[i].from} EUR. Companies in that range will NOT be found.`);
  }
}
if (sorted[sorted.length - 1].to < hi) {
  console.log(`!! GAP: nothing covers ${sorted[sorted.length - 1].to} - ${hi} EUR. Companies in that range will NOT be found.`);
}

s.bandQueue = bands;
console.log(`Seed bands (${bands.length}): ${bands.map((b) => b.from + '-' + b.to).join('  |  ')}`);

console.log('=== EmBRACE harvest: RUN START ===');
console.log(`County: ${cfg.county_name} (code ${cfg.county_code})  |  Size: ${cfg.size_category}`);
console.log(`Employees ${cfg.employees_from}-${cfg.employees_to}  |  Revenue ${cfg.revenue_from}-${cfg.revenue_to} EUR`);
console.log(`enrich_profiles: ${cfg.enrich_profiles === true}  |  test_mode: ${cfg.test_mode === true}`);
if (cfg.enrich_profiles !== true) {
  console.log('Profile enrichment is OFF: columns I-M stay blank. Fill them later with the enrich workflow.');
}
if (cfg.test_mode === true) console.log('test_mode is ON: stopping after 2 revenue bands.');

return [{ json: {} }];

// Pop the next revenue band off the queue.
const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');

if (cfg.test_mode === true && s.bandsProcessed >= 2) {
  console.log('test_mode: 2 bands done, stopping.');
  return [{ json: { done: true } }];
}

const band = (s.bandQueue || []).shift();
if (!band) return [{ json: { done: true } }];

s.currentBand = band;
s.bandCount = 0;
s.bandsProcessed++;

console.log(`=== BAND ${s.bandsProcessed}: revenue ${band.from} - ${band.to} EUR (${s.bandQueue.length} queued) ===`);
return [{ json: { done: false, page: 1, band_from: band.from, band_to: band.to } }];

// ScrapingBee renders JS by default (5 credits). The search results are
// server-rendered, so we ask for raw HTML (1 credit) and only retry with
// render_js on the very first query of the run -- see "Retry First Query With JS".
const RENDER_JS = false;

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const band = s.currentBand;
const page = Number($input.first().json.page) || 1;

const search_url = 'https://www.companywall.hr/pretraga?' + [
  'cr=EUR',
  `r=${cfg.county_code}`,
  'sbjact=t',
  'bly=2025',
  'dsm[0].Code=411',
  `dsm[0].From=${band.from}`,
  `dsm[0].To=${band.to}`,
  'dsm[1].Code=2138',
  `dsm[1].From=${cfg.employees_from}`,
  `dsm[1].To=${cfg.employees_to}`,
  'dsm[-1].Code=0',
  'dsm[-1].From=0',
  'dsm[-1].To=0',
  'xpnd=true',
  `p=${page}`,
].join('&');

const is_first_query = s.bandsProcessed === 1 && page === 1;

console.log(`--- band ${band.from}-${band.to}, page ${page}`);
return [{ json: { page, search_url, render_js: RENDER_JS, is_first_query, band_from: band.from, band_to: band.to } }];

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const page = Number($('Build Search URL').first().json.page) || 1;
const band = s.currentBand;
const raw = $input.first().json;

let companies = null;
let failed = false;
let reason = '';

if (raw && raw.error !== undefined) {
  failed = true;
  reason = typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300);
} else if (raw && Array.isArray(raw.companies)) {
  companies = raw.companies;
} else {
  failed = true;
  reason = 'ScrapingBee response had no "companies" array: ' + JSON.stringify(raw).slice(0, 300);
}

companies = (companies || []).filter((c) => c && (c.name || c.profile_url));

if (failed) {
  s.failedPages.push({ county: cfg.county_name, band: `${band.from}-${band.to}`, page, reason });
  console.log(`!! PAGE FAILED after retries -- band ${band.from}-${band.to} page ${page}: ${reason}`);
} else {
  s.bandCount = (s.bandCount || 0) + companies.length;
  console.log(`band ${band.from}-${band.to} page ${page}: ${companies.length} companies (band running total ${s.bandCount})`);
}

return [{ json: { page, failed, reason, count: companies.length, companies } }];

// One item per company. employees and revenue stay raw Croatian text on
// purpose; number cleanup happens manually, outside this workflow.
const src = $input.first().json;
const str = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) v = v.find((x) => x !== null && x !== undefined && String(x).trim() !== '') ?? '';
  return String(v).replace(/\s+/g, ' ').trim();
};
return (src.companies || []).map((c) => ({
  json: {
    name: str(c.name), profile_url_raw: str(c.profile_url), status: str(c.status),
    oib: str(c.oib), employees: str(c.employees), revenue: str(c.revenue), page: src.page,
  },
}));

// Extend the company item (search-page fields) with the profile-page fields.
// No Merge node: this is one sequential item, so we just add keys to it.
//
// The profile call returns RAW HTML (no extract_rules) and we parse it here.
// That is deliberate: it depends on nothing except the page's own Croatian
// labels, and it lets you SEE the page in this node's input when a field is
// missing. Add any label wording you find to LABELS below.
const base = $('Loop Over Companies').first().json;
const raw = $input.first().json;
const s = $getWorkflowStaticData('global');

const LABELS = {
  owner_director: ['Vlasnik', 'Vlasnici', 'Direktor', 'Direktori', 'Odgovorna osoba', 'Član uprave', 'Uprava'],
  email: ['E-mail', 'E-pošta', 'Email', 'E-mail adresa', 'Mail'],
  founding_date: ['Datum osnivanja', 'Datum upisa', 'Osnovan', 'Osnovana', 'Godina osnivanja'],
  nkd_code: ['NKD 2007', 'NKD', 'Šifra djelatnosti', 'Pretežita djelatnost', 'Djelatnost'],
  mbs: ['MBS', 'Matični broj subjekta', 'Matični broj'],
};

const ALL_LABELS = new Set(Object.values(LABELS).flat().map((l) => l.toLowerCase()));

const fields = { owner_director: '', email: '', founding_date: '', nkd_code: '', mbs: '' };

const html = typeof raw?.data === 'string' ? raw.data : (typeof raw === 'string' ? raw : '');
const failed = !!(raw && raw.error !== undefined) || !html;
const reason = failed
  ? (raw && raw.error !== undefined
      ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300))
      : 'ScrapingBee returned no HTML body')
  : '';

if (!failed) {
  const NAMED = {
    nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
    scaron: 'š', Scaron: 'Š', ccaron: 'č', Ccaron: 'Č', cacute: 'ć', Cacute: 'Ć',
    zcaron: 'ž', Zcaron: 'Ž', dstrok: 'đ', Dstrok: 'Đ', eacute: 'é', ndash: '-', mdash: '-',
  };

  const decode = (t) => t
    .replace(/&([A-Za-z][A-Za-z0-9]*);/g, (m, name) => (name in NAMED ? NAMED[name] : m))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));

  // Every tag boundary becomes a line break, so <span>MBS</span><span>123</span>
  // turns into "MBS" / "123" on consecutive lines.
  const lines = decode(
    html
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, '\n')
  )
    .split('\n')
    .map((l) => l.replace(/\s+/g, ' ').trim())
    .filter(Boolean);

  const esc = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const fromLabels = (labels) => {
    for (const label of labels) {
      const re = new RegExp('^' + esc(label) + '\\s*:?\\s*(.*)$', 'i');
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(re);
        if (!m) continue;
        const candidate = (m[1].trim() || lines[i + 1] || '').trim();
        if (candidate && candidate.length <= 300 && !ALL_LABELS.has(candidate.toLowerCase().replace(/:$/, ''))) {
          return candidate;
        }
      }
    }
    return '';
  };

  for (const key of Object.keys(fields)) fields[key] = fromLabels(LABELS[key]);

  // Email needs its own handling: the value next to the "E-mail" label is often
  // a link whose text is "Pošalji"/"Kontakt", not the address itself.
  const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
  const mailto = html.match(/mailto:([^"'?>\s]+)/i);
  if (mailto) {
    fields.email = decode(mailto[1]).trim();
  } else if (!EMAIL_RE.test(fields.email)) {
    const inLabel = fields.email.match(EMAIL_RE);
    const anywhere = lines.join(' ').match(EMAIL_RE);
    fields.email = (inLabel && inLabel[0]) || (anywhere && anywhere[0]) || '';
  }

  // Diagnostics: dump a readable slice of the page for the first company of the
  // run, and again whenever a field comes back empty, so the real label wording
  // is visible in the execution log.
  const missing = Object.keys(fields).filter((k) => !fields[k]);
  if (!s.loggedSample || missing.length) {
    if (!s.loggedSample) s.loggedSample = 0;
    if (s.loggedSample < 3) {
      s.loggedSample++;
      console.log(`--- PROFILE PAGE TEXT SAMPLE (${base.name}) ---`);
      console.log(`missing fields: ${missing.length ? missing.join(', ') : 'none'}`);
      console.log(lines.slice(0, 150).join(' | '));
      console.log('--- end sample ---');
    }
  }
} else {
  s.failedProfiles.push({ name: base.name, oib: base.oib, url: base.profile_url, page: base.page, reason });
  s.pageFailedProfiles = (s.pageFailedProfiles || 0) + 1;
  console.log(`!! PROFILE FETCH FAILED for ${base.name} (OIB ${base.oib}): ${reason}`);
  console.log('   Writing the row with search-page data only; profile columns left blank.');
}

return [{ json: { ...base, ...fields, profile_failed: failed } }];

// enrich_profiles is off: keep the search-page fields, leave I-M blank.
const base = $('Loop Over Companies').first().json;
return [{ json: { ...base, owner_director: '', email: '', founding_date: '', nkd_code: '', mbs: '', profile_failed: false } }];

// Single convergence point for both branches (enriched / not enriched), so the
// Sheets nodes downstream always have one node name to reference.
return $input.all();

// Emit EXACTLY the Sheet's header names as keys, nothing else.
//
// The append node maps by header name (mappingMode: autoMapInputData) rather
// than a schema stored in the node. A stored schema is compared positionally
// against the live header row on every run, and any drift throws
// "Column names were updated after the node's setup" -- which is what this
// avoids. Extra keys are ignored (handlingExtraData: ignoreIt) so the internal
// lowercase fields never leak into the sheet as new columns.
const c = $('Prepare Row').first().json;
const t = (v) => (v === null || v === undefined ? '' : String(v));

return [{ json: {
  "Name": t(c.name),
  "Profile URL": t(c.profile_url),
  "Status": t(c.status),
  "OIB": t(c.oib),
  "Employees": t(c.employees),
  "Revenue": t(c.revenue),
  "County": t(c.county),
  "Size Category": t(c.size_category),
  "Owner/Director": t(c.owner_director),
  "Email": t(c.email),
  "Founding Date": t(c.founding_date),
  "NKD Code": t(c.nkd_code),
  "MBS": t(c.mbs),
} }];

const c = $('Prepare Row').first().json;
const s = $getWorkflowStaticData('global');
s.written = (s.written || 0) + 1;
console.log(`Written: ${c.name} (OIB ${c.oib})`);
return $input.all();

const c = $('Prepare Row').first().json;
const s = $getWorkflowStaticData('global');
s.skipped = (s.skipped || 0) + 1;
console.log(`Skipped duplicate: ${c.oib} (${c.name})`);
return $input.all();

// Safety net: the cap means a band should never exceed 3 pages. If the site
// ever clamps p= to the last page instead of returning empty, this stops the
// band rather than looping forever.
const MAX_PAGES_PER_BAND = 10;

const page = Number($('Build Search URL').first().json.page) || 1;
const nextPage = page + 1;
const endBand = nextPage > MAX_PAGES_PER_BAND;
if (endBand) console.log(`!! Band hit MAX_PAGES_PER_BAND (${MAX_PAGES_PER_BAND}) -- ending band early.`);

return [{ json: { page: nextPage, endBand } }];

// A band that came back at the cap is truncated, not complete: bisect it and
// queue both halves. Under the cap means we have genuinely seen everything.
const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const RESULT_CAP = Number(cfg.result_cap) || 60;

const band = s.currentBand;
const found = s.bandCount || 0;

if (found >= RESULT_CAP && band.to > band.from) {
  const mid = Math.floor((band.from + band.to) / 2);
  // unshift = depth first, so bands get narrow quickly instead of queueing
  // a huge frontier of wide bands.
  s.bandQueue.unshift({ from: mid + 1, to: band.to });
  s.bandQueue.unshift({ from: band.from, to: mid });
  s.cappedBands.push({ from: band.from, to: band.to, found });
  console.log(`Band ${band.from}-${band.to} returned ${found} (cap ${RESULT_CAP}) -> splitting into ${band.from}-${mid} and ${mid + 1}-${band.to}`);
} else if (found >= RESULT_CAP) {
  s.cappedBands.push({ from: band.from, to: band.to, found, unsplittable: true });
  console.log(`!! Band ${band.from}-${band.to} is AT THE CAP but cannot be narrowed further.`);
  console.log('   Companies beyond the first ' + RESULT_CAP + ' at this exact revenue are unreachable via the revenue filter.');
  console.log('   Narrow employees_from/employees_to and re-run to reach them.');
} else {
  s.completedBands.push({ from: band.from, to: band.to, found });
  console.log(`Band ${band.from}-${band.to} COMPLETE: ${found} companies (under cap).`);
}

console.log(`Run totals so far: ${s.written} written, ${s.skipped} duplicates skipped, ${s.bandQueue.length} bands queued.`);
return [{ json: {} }];

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const unsplittable = (s.cappedBands || []).filter((b) => b.unsplittable);

console.log('=== EmBRACE harvest: RUN COMPLETE ===');
console.log(`County: ${cfg.county_name} (code ${cfg.county_code})  |  Size: ${cfg.size_category}`);
console.log(`Rows written: ${s.written}  |  Duplicates skipped: ${s.skipped}`);
console.log(`Bands processed: ${s.bandsProcessed}  (${(s.completedBands || []).length} complete, ${(s.cappedBands || []).length} were at the cap and split)`);
console.log(`Pages skipped after failed retries: ${(s.failedPages || []).length}`);
if ((s.failedPages || []).length) console.log(JSON.stringify(s.failedPages, null, 2));
if (unsplittable.length) {
  console.log(`!! ${unsplittable.length} band(s) hit the cap and could not be narrowed -- some companies were NOT reachable:`);
  console.log(JSON.stringify(unsplittable, null, 2));
}
if (cfg.enrich_profiles !== true) console.log('Profile columns are blank by design (enrich_profiles = false).');

return [{ json: {
  county: cfg.county_name, size_category: cfg.size_category,
  rows_written: s.written, duplicates_skipped: s.skipped,
  bands_processed: s.bandsProcessed, bands_complete: (s.completedBands || []).length,
  bands_split: (s.cappedBands || []).length, unreachable_bands: unsplittable,
  failed_pages: s.failedPages || [],
} }];
